The shutdown in decUsage has the potential to cause a deadlock.

       public void decUsage() {
            synchronized (usagelock) {
                this.count--;
                if ( this.count == 0 ) {
                    this.shutdown();
                }
            }
        }

could be 
         public void decUsage() {
            boolean shutdown = false;
            synchronized (usagelock) {
                this.count--;
                if ( this.count == 0 ) {
                    shutdown = true;
                }
            }
            if ( shutdown ) {
                  this.shutdown();
            }
        }

